presets.css:
/* =========================================================
   Puff · iOS 16 iMessage 完美复刻版 (夜间模式终极修复版)
   ========================================================= */

/* ========== A. 主题变量 (iMessage 蓝灰配色) ========== */
.chat-thread {
  --dress-chat-bg-overlay: #ffffff;

  /* 顶栏：极简微透 */
  --dress-header-bg: rgba(250, 250, 250, 0.85);
  --dress-header-blur: 20px;
  --dress-header-border: rgba(0, 0, 0, 0.05);
  --dress-header-radius: 0px;
  --dress-header-shadow: none;
  --dress-header-title-color: #000000;
  --dress-header-title-size: 16px;
  --dress-header-title-weight: 600;
  --dress-header-icon-color: #007AFF;

  /* 我方气泡：iMessage 经典蓝，无阴影 */
  --dress-bubble-me-bg: #007AFF;
  --dress-bubble-me-fg: #ffffff;
  --dress-bubble-me-border: none;
  --dress-bubble-me-shadow: none; 
  --dress-bubble-me-radius: 18px;

  /* 对方气泡：iMessage 经典灰，无阴影 */
  --dress-bubble-them-bg: #E5E5EA;
  --dress-bubble-them-fg: #000000;
  --dress-bubble-them-border: none;
  --dress-bubble-them-shadow: none;
  --dress-bubble-them-radius: 18px;

  /* 输入胶囊：极简 */
  --dress-compose-bar-bg: rgba(250, 250, 250, 0.85);
  --dress-compose-bar-fg: #000000;
  --dress-compose-bar-radius: 20px;
  --dress-compose-bar-border: 1px solid rgba(0, 0, 0, 0.1);
  --dress-compose-bar-shadow: none;
  --dress-compose-bar-blur: blur(20px);

  --dress-timestamp-color: #8E8E93;
}

/* ★ 暗黑模式适配 (深度定制纯黑版) ★ */
html[data-theme="dark"] .chat-thread {
  --dress-chat-bg-overlay: #000000;
  --dress-header-bg: #000000; 
  --dress-header-border: rgba(255, 255, 255, 0.05);
  --dress-header-title-color: #ffffff; 
  --dress-header-icon-color: #0A84FF;

  --dress-bubble-me-bg: #0A84FF;
  --dress-bubble-me-fg: #ffffff;

  --dress-bubble-them-bg: #262628; 
  --dress-bubble-them-fg: #ffffff;

  --dress-compose-bar-bg: #000000; 
  --dress-compose-bar-border: 1px solid rgba(255, 255, 255, 0.1);
  --dress-timestamp-color: #8E8E93;
}

/* ========== B. 修复滚动区域 & 历史消息按钮防遮挡 ========== */
.chat-thread-scroll {
  padding-top: calc(env(safe-area-inset-top, 20px) + 110px) !important; 
  padding-bottom: 30px !important; 
}
.chat-history-fold-wrap,
.chat-history-fold {
  margin-top: 10px !important; 
  position: relative !important;
  z-index: 10 !important; 
}

/* ========== C. 仿 iOS 16 iMessage 顶栏 ========== */
.chat-thread-top {
  padding: 0 !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
}
.chat-thread-pill {
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 !important;
  border-radius: 0 !important; 
  border: none !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.05) !important; 
  padding: calc(env(safe-area-inset-top, 20px) + 8px) 16px 8px 16px !important; 
  height: auto !important;
  box-sizing: border-box !important;
  background-color: #F4F4F4 !important; 
  box-shadow: none !important; 
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
html[data-theme="dark"] .chat-thread-pill {
  background-color: #000000 !important; 
  border-bottom: 1px solid #1C1C1E !important; 
}
.chat-thread-center {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  margin-top: 2px;
}

/* 头像与名字 */
.chat-thread-center::before {
  content: '';
  display: block;
  width: 50px; 
  height: 50px;
  margin-top: -6px; 
  border-radius: 50%; 
  background-image: url('https://i.postimg.cc/T1w61jzj/IMG-5293.png'); 
  background-size: cover;
  background-position: center;
  margin-bottom: 7px; 
  background-color: #E5E5EA; 
}
html[data-theme="dark"] .chat-thread-center::before {
  background-color: #3A3A3C;
}
.chat-thread-center h2 {
  font-size: 11px !important; 
  font-weight: 500 !important;
  line-height: 1 !important;
  color: #000 !important;
}
html[data-theme="dark"] .chat-thread-center h2 {
  color: #FFFFFF !important; 
}

/* 顶栏幽灵按钮区 */
.chat-thread-top .chat-back {
  position: relative !important; 
  width: 32px !important;
  height: 32px !important;
  background-image: url('https://i.postimg.cc/fbnDC9dd/IMG-5294.png') !important;
  background-color: transparent !important; 
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
}
.chat-thread-top .chat-back * { opacity: 0 !important; } 

/* 返回按钮右侧装饰图 */
.chat-thread-top .chat-back::after {
  content: '';
  position: absolute;
  left: 24px; 
  top: 50%;
  transform: translateY(-50%);
  width: 34px; 
  height: 34px;
  background-image: url('https://i.postimg.cc/FRbyz3y1/IMG-5297.png');
  background-size: contain;
  background-position: left center; 
  background-repeat: no-repeat;
  pointer-events: none; 
  display: block !important;
}
.chat-thread-top .chat-thread-head-more {
  width: 32px !important;
  height: 32px !important;
  background-image: url('https://i.postimg.cc/8CQN46vW/IMG-5295.png') !important;
  background-color: transparent !important; 
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  border-radius: 4px;
}
.chat-thread-top .chat-thread-head-more * { opacity: 0 !important; } 

.chat-thread-top .chat-thread-head-xinsheng {
  width: 32px !important;
  height: 32px !important;
  background-color: transparent !important; 
  border-radius: 4px;
}
.chat-thread-top .chat-thread-head-xinsheng * { opacity: 0 !important; }

/* ========== D. 消息行与气泡 (拉丝水滴尾巴) ========== */

/* 1. 隐藏原生名字，头像靠下对齐 */
.chat-msg-name { display: none !important; }
.chat-ava { border-radius: 50%; margin-top: auto; }

/* 2. 气泡基础设定 */
.chat-bubble, .chat-bubble-primary, .chat-msg-body {
  position: relative !important; 
  overflow: visible !important;
}
.chat-bubble {
  line-height: 1.4 !important;
  padding: 6px 12px !important;
}
.chat-msg.is-me .chat-bubble-primary,
.chat-msg.is-them .chat-bubble-primary {
  border-radius: 18px !important; 
  z-index: 1 !important; 
}

/* 3. 贴图尾巴 (我方 - 最新贴图版) */
.chat-msg.is-me .chat-bubble-primary::after {
  content: "" !important;
  position: absolute !important;
  width: 20px !important; 
  height: 16px !important;

  /* 你的完美参数 */
  bottom: -6px !important; 
  right: -23px !important; 

  /* 自动跟随主题变量，暗黑模式完美适配 */
  background-color: var(--dress-bubble-me-bg) !important; 

  /* 最新贴图 URL */
  -webkit-mask-image: url("https://i.postimg.cc/Z5jrsSxD/IMG-5393.png") !important;
  mask-image: url("https://i.postimg.cc/Z5jrsSxD/IMG-5393.png") !important;
  -webkit-mask-size: contain !important;
  mask-size: contain !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
  -webkit-mask-position: bottom left !important;
  mask-position: bottom left !important;

  z-index: 1 !important; 
}

/* 4. 贴图尾巴 (对方 - 最新贴图镜像版) */
.chat-msg.is-them .chat-bubble-primary::after {
  content: "" !important;
  position: absolute !important;
  width: 20px !important;
  height: 16px !important;

  /* 对称的完美参数 */
  bottom: -6px !important;
  left: -22.5px !important; 

  transform: scaleX(-1) !important; 

  /* 自动跟随主题变量 */
  background-color: var(--dress-bubble-them-bg) !important; 

  /* 最新贴图 URL */
  -webkit-mask-image: url("https://i.postimg.cc/mk6wnG4Z/IMG-5392.png") !important;
  mask-image: url("https://i.postimg.cc/mk6wnG4Z/IMG-5392.png") !important;
  -webkit-mask-size: contain !important;
  mask-size: contain !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
  -webkit-mask-position: bottom left !important;
  mask-position: bottom left !important;

  z-index: 1 !important;
}

/* 5. 气泡间距控制 */
.chat-msg {
  margin-bottom: 0 !important; 
  padding-bottom: 0 !important; 
  margin-top: 12px !important; 
}
.chat-thread-scroll > *:has(.chat-msg.is-me) + *:has(.chat-msg.is-me) .chat-msg,
.chat-thread-scroll > *:has(.chat-msg.is-them) + *:has(.chat-msg.is-them) .chat-msg {
  margin-top: 3px !important; 
}

/* ========== E. 时间戳与系统通知 (被我找回来了！) ========== */

/* 1. 彻底隐藏多余的气泡底部时间 (死死按住，绝对不准出来) */
.chat-msg-time {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  opacity: 0 !important;
}

/* 2. 系统时间戳 (两行居中 iMessage 风格) */
.chat-msg-timestamp {
  background: transparent !important; 
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;

  color: #8E8E93 !important; 
  font-size: 11px !important;
  font-weight: 600 !important; 
  letter-spacing: 0.2px !important;

  padding: 24px 0 12px 0 !important; 
  width: 100%;

  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 4px !important; 
}

/* 强行注入第一行的 "iMessage" */
.chat-msg-timestamp::before {
  content: "iMessage";
  display: block;
  color: #8E8E93;
  font-weight: 600;
}

html[data-theme="dark"] .chat-msg-timestamp,
html[data-theme="dark"] .chat-msg-timestamp::before {
  color: #98989D !important; 
}

/* 3. 系统通知灰字 (撤回等) */
.chat-thread-notice,
.chat-thread-notice-hint,
.chat-recall-text {
  color: #8E8E93 !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  background: transparent !important;
}
html[data-theme="dark"] .chat-thread-notice,
html[data-theme="dark"] .chat-thread-notice-hint,
html[data-theme="dark"] .chat-recall-text {
  color: #98989D !important;
}

/* ========== F. 仿 iOS 16 iMessage 底栏 (被我找回来了！) ========== */
.chat-compose {
  background-color: #D0D4D8 !important; 
  border-top: none !important; 
  padding: 0 0 76px 0 !important; 
  position: relative;
  z-index: 100;
}
html[data-theme="dark"] .chat-compose {
  background-color: #000000 !important; 
}

/* 底部长条 URL */
.chat-compose::after {
  content: '';
  position: absolute;
  bottom: -10px; 
  left: 0;
  right: 0;
  height: 140px;
  background-image: url('https://i.postimg.cc/cHYcyP9P/IMG-5291.png');
  background-size: contain; 
  background-position: left center; 
  background-repeat: no-repeat;
  pointer-events: none;
  transition: opacity 0.2s ease;
}
html[data-theme="dark"] .chat-compose::after {
  background-image: url('https://i.postimg.cc/cHYcyP9P/IMG-5291.png');
}

/* 上层容器 */
.chat-compose-bar {
  background-color: #FFFFFF !important; 
  margin: 0 !important; 
  border-radius: 0 !important; 
  width: 100% !important; 
  box-sizing: border-box !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 8px 16px 6px 16px !important; 
  position: relative;
  display: flex;
  align-items: center;
}
html[data-theme="dark"] .chat-compose-bar {
  background-color: #000000 !important; 
}

/* 上层左侧两个图标 */
.chat-compose-bar::before {
  content: '';
  position: absolute;
  left: 12px;
  bottom: 0px; 
  width: 44px; 
  height: 44px;
  background-image: url('https://i.postimg.cc/NFm9t3LP/IMG-5282.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  pointer-events: none;
}
.chat-compose-bar::after {
  content: '';
  position: absolute;
  left: 68px; 
  bottom: 0px; 
  width: 44px;
  height: 44px;
  background-image: url('https://i.postimg.cc/fRvsSHfD/IMG-5390.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  pointer-events: none;
}

/* 圆角输入框 */
.chat-compose-input {
  background-color: #FFFFFF !important; 
  border: 1.5px solid rgba(89, 89, 91, 0.45) !important; 
  border-radius: 18px !important; 
  margin-left: 100px !important; 
  padding: 5px 40px 5px 12px !important; 
  width: calc(100% - 100px) !important; 
  min-height: 32px !important; 
  box-shadow: none !important;
}
html[data-theme="dark"] .chat-compose-input {
  background-color: #000000 !important; 
  border: 1.5px solid #424242 !important; 
  color: #FFF !important;
}

/* SVG 占位文字 */
.chat-compose-input::placeholder { color: transparent !important; font-size: 0 !important; opacity: 0 !important; }
.chat-compose-input::-webkit-input-placeholder { color: transparent !important; font-size: 0 !important; opacity: 0 !important; }
.chat-compose-input:placeholder-shown {
  background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='150' height='24'%3E%3Ctext x='0' y='17' fill='%238E8E93' font-size='15' font-family='system-ui, sans-serif'%3EiMessage信息%3C/text%3E%3C/svg%3E") !important;
  background-repeat: no-repeat !important;
  background-position: 12px center !important; 
}
html[data-theme="dark"] .chat-compose-input:placeholder-shown {
  background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='150' height='24'%3E%3Ctext x='0' y='17' fill='%23424242' font-size='15' font-family='system-ui, sans-serif'%3EiMessage信息%3C/text%3E%3C/svg%3E") !important;
}

/* 幽灵按钮区 */
.chat-compose-plus {
  position: absolute !important; left: 4px !important; bottom: -44px !important; width: 32px !important; height: 32px !important; margin: 0 !important; background: transparent !important; border-radius: 6px !important; z-index: 999 !important; transition: opacity 0.2s ease;
}
.chat-compose-plus * { opacity: 0 !important; } 

.chat-compose-icon.is-send,
.chat-compose-icon.is-send.ready,
.chat-compose-icon.is-reply {
  position: absolute !important; right: 12px !important; bottom: -38px !important; width: 32px !important; height: 32px !important; margin: 0 !important; background: transparent !important; border-radius: 6px !important; z-index: 999 !important; display: block !important; transition: all 0.3s ease;
}
.chat-compose-icon.is-send *, .chat-compose-icon.is-reply * { opacity: 0 !important; } 

.chat-compose-icon.is-voice {
  position: absolute !important; right: 22px !important; bottom: 12px !important; width: 20px !important; height: 20px !important; margin: 0 !important; background-color: transparent !important; background-image: url('https://i.postimg.cc/Dyqj94J6/IMG-5292.png') !important; background-size: contain !important; background-position: center !important; background-repeat: no-repeat !important; border-radius: 0 !important; z-index: 999 !important; transition: opacity 0.2s ease;
}
.chat-compose-icon.is-voice * { opacity: 0 !important; } 
html[data-theme="dark"] .chat-compose-icon.is-voice { background-image: url('https://i.postimg.cc/MTzfGTzf/IMG-5301.png') !important; }

/* =========================================================
   ★ 多选防遮挡 ★
   ========================================================= */
.chat-thread:has(.chat-msg-multi-bar) .chat-thread-scroll {
  padding-bottom: 120px !important; 
}
.chat-msg-multi-bar {
  background-color: rgba(250, 250, 250, 0.9) !important; backdrop-filter: blur(20px) !important; -webkit-backdrop-filter: blur(20px) !important; border-top: 1px solid rgba(0, 0, 0, 0.05) !important; padding-bottom: env(safe-area-inset-bottom, 20px) !important;
}
html[data-theme="dark"] .chat-msg-multi-bar {
  background-color: rgba(30, 30, 30, 0.9) !important; border-top: 1px solid rgba(255, 255, 255, 0.05) !important;
}

/* =========================================================
   ★ G. 翻译分离式设计 (电影字幕风 + 挖坑防遮挡) ★
   ========================================================= */

/* 1. 电影字幕风：把翻译拽到气泡正下方 */
.chat-bubble-trans-inline {
  position: absolute !important;
  top: calc(100% + 2px) !important; 
  z-index: 999 !important;

  background-color: #000000 !important; 
  color: #FFFFFF !important; 
  font-size: 11px !important; 
  line-height: 1.3 !important; 
  font-weight: 500 !important;

  /* 👉 调整：字离黑卡片边缘间距再缩小一点 (极度紧凑) */
  padding: 1px 4px !important; 
  border-radius: 0px !important; 
  border: none !important; 

  width: max-content !important;
  max-width: 65vw !important;
  white-space: normal !important;
  word-wrap: break-word !important;
}

/* 2. 物理挖坑：给整条消息底部留出更大的空白 */
.chat-msg:has(.chat-bubble-trans-inline) {
  /* 👉 调整：开翻译时气泡间距调大一点，往下推一点 (char打字习惯两行及以上可以把24px调大至36px左右) */
  margin-bottom: 24px !important; 
  overflow: visible !important; /* 解除外壳裁剪 */
}

/* 3. 终极清道夫：消灭气泡内部的横线和空隙！ */
.chat-msg:has(.chat-bubble-trans-inline) .chat-msg-body {
  display: block !important; 
  padding-bottom: 0 !important;
  margin-bottom: 0 !important;
  border: none !important;
}
.chat-msg:has(.chat-bubble-trans-inline) hr {
  display: none !important;
}
.chat-msg:has(.chat-bubble-trans-inline) .chat-msg-body * {
  border-color: transparent !important;
  box-shadow: none !important;
}
.chat-msg:has(.chat-bubble-trans-inline) .chat-msg-body *:empty:not(img):not(svg):not(br) {
  display: none !important;
}

/* 4. 恢复气泡底部的紧凑厚度 */
.chat-msg:has(.chat-bubble-trans-inline) .chat-bubble {
  padding-bottom: 6px !important;
}

/* 5. 我方靠右，对方靠左 */
.chat-msg.is-me .chat-bubble-trans-inline { right: 0 !important; left: auto !important; text-align: right !important; }
.chat-msg.is-them .chat-bubble-trans-inline { left: 0 !important; right: auto !important; text-align: left !important; }

/* 6. 暗黑模式适配 */
html[data-theme="dark"] .chat-bubble-trans-inline { background-color: #3A3A3C !important; color: #FFFFFF !important; }

/* =========================================================
   ★ H. 推演按钮调整 (位置左移 + 样式美化)
   ========================================================= */

.chat-thinking-chip {
  /* 🌟 核心：向左移动！ */
  /* 数字越大，向左移得越多。如果你想向右移，就把负号去掉变成正数 */
  transform: translateX(-18px) !important; 

  /* 顺便固定一下它的 iOS 极简风格 (防变形) */
  background: rgba(0, 0, 0, 0.05) !important;
  color: #8E8E93 !important;
  border-radius: 999px !important;
  padding: 2px 10px !important;
  font-size: 11px !important;
}

/* 暗黑模式适配 */
html[data-theme="dark"] .chat-thinking-chip {
  background: rgba(255, 255, 255, 0.08) !important;
  color: #98989D !important;
}
